		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'eventAt' THEN r.[EventAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'eventAt' THEN r.[EventAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'latitude' THEN r.[Latitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'latitude' THEN r.[Latitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'longitude' THEN r.[Longitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'longitude' THEN r.[Longitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperatureC' THEN r.[TemperatureC] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperatureC' THEN r.[TemperatureC] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'photoUrl' THEN r.[PhotoUrl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'photoUrl' THEN r.[PhotoUrl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END DESC,
